-- GENERATED by `wfj generate` from data/gossip/gossip-71.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["71023fd1785b47b3"] = { "La tua istruzione è quasi completa. Un ultimo compito è tutto ciò che ti separa dal culmine di tutti i tuoi sforzi...", "." },
  ["7103a8535cf7635a"] = { "Non lasciare che il tintinnio delle campanelle ti distragga dal tintinnio delle monete in tasca! Compra le leccornie della Masseria Buongusto per le tue feste del Grande Inverno!", "." },
  ["7111b6893a34384a"] = { "%s comincia a creare una copia di sé!", "." },
  ["711ccad01859ea2d"] = { "Se cuciture logore d'abominio vuoi trovare, a Stratholme ti tocca andare.\n\nUn tempo città natale del Lightbringer in persona, ora è invasa dai servitori di Kel'Thuzad.\n\nSfida i pericoli della città in fiamme e abbatti i carnosi abomini! Prendi da loro il tuo premio: cuciture logore d'abominio!", "." },
  ["7132c400d546429d"] = { "In questo luogo, oscurità e ombre sono strumenti da usare e gettare a piacimento.", "." },
  ["71366d694883fbe3"] = { "Come vanno i tuoi viaggi, {name}? Ho sentito racconti delle tue avventure: a quanto pare hai avuto molto da fare. Ora vediamo cosa hai imparato mentre eri via.", "." },
  ["7137a29d0d7777e3"] = { "L'incubo di Ursal è finito! Siamo liberi!", "." },
  ["714ac09837e1fb4e"] = { "Questi tizi del Mithril Order sono delle femminucce.", "." },
  ["714de0ad814c40be"] = { "Mia Royal Dreadguard, vi occuperete di questa faccenda come si addice al vostro rango. Altrimenti, rimpiangerete di non averlo fatto.", "." },
  ["71529edc98f8c29f"] = { "Guarda dove metti i piedi, {race}. Noi della Brotherhood of the Light non siamo indulgenti come i nostri confratelli quando si tratta di fare giustizia di chi vorrebbe recare danno a questo mondo.\n\nGuai a chi fa adirare Korfax.\n\nOra, se non hai affari con me o con gli altri membri della Brotherhood, ti prego di andartene, così che possiamo proseguire la nostra riunione.", "." },
  ["7152b03fe13a0797"] = { "Cerchi un istruttore di Alchimia, eh? Vengo proprio da lì, io. Troverai la signora Berryfizz a Tinker Town, dove si radunano gli gnomi.\n\n::sospira:: ...perché, oh perché non ho preso la pozione blu?", "." },
  ["715ce4dcb78c7396"] = { "Sei ancora qui? La tua stoltezza è divertente! La sgualdrina dell'⟦Argent Dawn=Alba d'Argento⟧ non deve soffrire invano. Vattene subito e sarà risparmiata!", "." },
  ["71645909346e1878"] = { "Grazie! Grazie, <sacerdote/sacerdotessa>. Ora posso affrontare quei wendigo con la Luce dalla mia parte!", "." },
  ["7168498b5d84f87b"] = { "%s scompare tra le nebbie.", "." },
  ["71740bed47311160"] = { "Jocaste è stata la più grande cacciatrice del suo tempo. Oggi la trovi all'⟦Cenarion Enclave=Enclave Cenariana⟧, dove insegna a chi muove i primi passi sulla via del cacciatore.", "." },
  ["717b2701aa36cff2"] = { "È Balthus Stoneflayer quello da cercare per la Scuoiatura. Se una cosa si può scuoiare, lui può insegnarti come. Fai due passi fino al Finespindle's Leather Goods, sul lato nord della ⟦Great Forge=Grande Forgia⟧.", "." },
  ["718049b28f247d4e"] = { "PERCHÉ si trova nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧?", "." },
  ["7180be2e92050b51"] = { "Chi osa risvegliare Aquementas?", "." },
  ["718b5c6114347fb5"] = { "Desidero questa quintessenza eterna, duca Idraxis.", "." },
  ["718f1f87b4d97fd0"] = { "Le conoscenze di Cyndra in alchimia sono un po' limitate, ma di sicuro bastano per iniziare. Pratica la sua arte appena a est della locanda di Dolanaar.", "." },
  ["719925d340741a17"] = { "Ti siamo grati per l'aiuto nel cercare quel corriere, {name}.\n\nMentre eri via, Kin ha visto uno speziale uscire da quella stessa casa a sud di qui. Non ho dubbi che stiano tramando qualcosa di losco: mi serve solo una prova prima di fare qualcosa di avventato.\n\nHai avuto fortuna?", "." },
  ["719ae405f02f7d81"] = { "Sciocchi.", "." },
  ["719fcc8c5211564c"] = { "Vrok dice che il mirino del fucile di Grumlar è starato. Mi sa che dovrei controllarlo.", "." },
  ["71a5c7bcc28b338d"] = { "Ti congelerò il sangue nelle vene!", "." },
  ["71abc13cb8502d5e"] = { "È bello vederti in buona salute, {name}. Le gloriose battaglie che hai combattuto toccano ogni forma di vita su questo pianeta. Hakkar non deve mai lasciare i confini di ⟦Zul'Gurub=Zul'gurub⟧, o il mondo crollerà di certo sotto la sua fame immensa.\n\nDammi il tuo talismano e ne amplificherò la forza. Usa l'⟦Strength of Mugamba=Amuleto della Forza di Mugamba⟧ per punire i nostri nemici!", "." },
  ["71b064ba5d4854fd"] = { "Parlami del Cult of the Damned.", "." },
  ["71b17c15c95edf55"] = { "Non preoccuparti per me! Uccidi questa bestia orrenda e purifica il mondo dalla sua lurida contaminazione!", "." },
  ["71b8faa8fe9ce3ae"] = { "Non mescolare la pozione così, contadino maldestro! No, non smettere nemmeno di mescolarla! Lascia perdere... dammi quel mestolo prima di appiccare un incendio. Salverò quel che posso. Ora fai attenzione.", "." },
  ["71bdbaf0ded81376"] = { "Prendi una pietra dal tavolo, {name}. Ti servirà per la tua missione.", "." },
  ["71ccb961415c068a"] = { "%s afferra il coniglio e gli versa il liquido in gola, poi lo rimette nella gabbia.", "." },
  ["71cf8ff062d651f1"] = { "Beh, non so fin dove riuscirò ad arrivare in questo stato... mi sento un po' svenire...", "." },
  ["71daee17a41374ec"] = { "Troppo tardi, amici! La corruzione di Nefarius ha preso il sopravvento... non riesco... a controllarmi.", "." },
  ["71ddaaa6086c6056"] = { "Spiriti degli ⟦Highborne=Alti Nobili⟧! Trovate pace! Il ⟦Crystal of Zin-Malor=Cristallo di Zin-Malor⟧ è di nuovo intero!", "." },
  ["71ea3ebc5d16110f"] = { "Ti do il benvenuto alla Calmbreeze Inn, <viaggiatore/viaggiatrice>. Gradisci qualcosa per ristorarti?", "." },
  ["71f07c8458ebe4d2"] = { "Ahah!", "." },
  ["71f4a879500d9751"] = { "Non fermerai mai i Reietti, {race}. La Dama Oscura ti farà soffrire.", "." },
  ["71fabdb09e0cbf97"] = { "Aha! Ecco qua!", "." },
  ["71fbfad1e2055d64"] = { "Ti do il benvenuto alle Fairweather Stables! Mi piacerebbe darti uno dei nostri splendidi galestrider, ma sembra che tu non abbia ancora abbastanza esperienza per cavalcarne uno.\r\n\nA volte sono capricciosi e tendono a disarcionare i cavalieri inesperti, se non li si sa gestire. Sarà un vero piacere darti l'addestramento quando avrai più esperienza come avventuriero e abbastanza monete!", "." },
})
